def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0 if hp > 3 else 42.0
        return float(max(0.0, min(budget, base)))

    slots = max(1, int(supply // WATER_REQ))
    total_players = 1 + len(alive)
    scarcity = total_players - slots

    prev_bids = []
    urgent_prev_bids = []
    rich_pressure = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_prev_bids.append(float(pbid))
        if opp.get('budget', 0) > budget:
            rich_pressure += 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if scarcity >= 3:
        base = 72.0
    elif scarcity == 2:
        base = 58.0
    elif scarcity == 1:
        base = 44.0
    else:
        base = 26.0

    if supply >= 24:
        base -= 8.0
    elif supply <= 16:
        base += 8.0

    if danger >= 5:
        bid = max(base + 25.0, urgent_high + 3.0, highest_prev * 0.92)
    elif danger >= 3:
        bid = max(base + 12.0, urgent_high + 2.0, highest_prev * 0.72)
    elif danger >= 1:
        bid = max(base + 4.0, highest_prev * 0.58)
    else:
        if scarcity <= 0:
            bid = max(16.0, highest_prev * 0.35)
        else:
            bid = max(base, urgent_high + 1.5, highest_prev * 0.5)

    if rich_pressure >= 2 and danger <= 1:
        bid -= 6.0

    if day >= 8 and hp <= 5:
        bid += 8.0

    reserve_floor = 10.0 if day < 8 else 0.0
    affordable = max(0.0, budget - reserve_floor)
    bid = min(bid, affordable)

    if danger >= 5 and budget > 0:
        bid = max(bid, min(budget, 62.0))

    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate reaction
    yesterday_bids = []
    yesterday_states = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            yesterday_bids.append(bid)
            yesterday_states.append((opp, bid, prev))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure heuristic: if someone bid extremely high yesterday, they likely overbid.
    # Use that to avoid matching unless our HP is critical.
    critical_hp = my_status['hp'] <= 2

    # Supply-based aggressiveness: when supply is low, competition for water is more costly.
    # We'll bid enough to beat typical mid bids, but not chase extremes.
    if supply <= float(MIN_SUPPLY) + 0.5:
        base = DAILY_SALARY * 0.65
    elif supply <= float(MIN_SUPPLY) + 5.0:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.45

    # If opponents previously overreached (very high bid), we can shade downward.
    # If our HP is critical, we bid higher to secure water.
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        if critical_hp:
            target = DAILY_SALARY * 0.95
        else:
            target = min(base, highest_prev_bid * 0.55)
    else:
        if critical_hp:
            target = max(base, DAILY_SALARY * 0.85)
        else:
            # If there were moderate-high bids, slightly outbid the median-ish level.
            # Use max of base and a fraction of highest_prev_bid to stay competitive.
            target = max(base, highest_prev_bid * 0.6)

    # Budget safety: never exceed our budget.
    bid = min(my_status['budget'], target)

    # If we have many no-water days, increase bid to avoid further HP loss.
    if my_status.get('no_water_days', 0) >= 2:
        bid = min(my_status['budget'], max(bid, DAILY_SALARY * 0.75))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

