        if prev_bids:
            avg_prev = sum(prev_bids) / len(prev_bids)
            target = min(avg_prev * 0.8, DAILY_SALARY * 0.6)
        else:
            target = DAILY_SALARY * 0.5
        return min(budget, max(target, 0.1))
